OUT=Path('.cache/batch200/drafts/rewrite_st');OUT.mkdir(parents=True,exist_ok=True)
ASSIGN=json.loads(Path('.cache/batch200/rewrite_st.json').read_text())
N=[['拉丁语 navis','船']]
NAVIG=N+[['拉丁语 navis + agere → navigare','船 + 驱动 → 驾船航行']]
NAVIGABLE=NAVIG+[['拉丁语 navigabilis → 法语 navigable / 直接借入英语','可供船通过的'],['英语 navigable','可航行的；可顺利浏览、穿行的']]
CIRC=NAVIG+[['拉丁语 circum- + navigare → circumnavigare / circumnavigatus','围绕 + 航行 → 绕行一周'],['英语 circumnavigate','环航、绕行']]
B=[['拉丁语 bene','好、善；以好的方式']]
BENIGN=B+[['拉丁语 benignus → 古法语 benigne','历史上联系“出身良好” → 友善、温和'],['中古英语 benigne → benign','和善的；温和无害的；良性的']]
BENEF=B+[['拉丁语 bene + facere 一系 → beneficus / beneficium','做好事 → 善意、恩惠、利益']]
BENEFICIAL=BENEF+[['拉丁语 beneficialis → 古法语 bénéficial / 直接借入英语','有益的、与恩惠有关的'],['英语 beneficial','能带来实际好处的']]
VOL=B+[['拉丁语 bene + volens〔velle 的现在分词〕','好 + 想要 → 希望别人好']]
W=[
E('navy','/ˈneɪvi/','海军；藏蓝色','最初是成群的船，后来是一个国家组织起来的海上军力；制服的颜色又留下藏蓝色义。','经古法语 navie 接拉丁 navigia，是 navigium“船”的复数，远接 navis；不是英语 nave + -y。',N+[['拉丁语 navigium / 复数 navigia → 古法语 navie','船 → 舰船队伍'],['中古英语 navie → navy','舰队 → 海军；navy blue 又简称 navy']],'join the navy 是参军进入海军；a navy jacket 是藏蓝色夹克。军种是机构，单次出动的一群船可以称 fleet。','join the navy；serve in the navy；a navy suit。','naval 说与海军、舰船有关；navy 作颜色词时说深蓝色。',('Her brother served in the navy for ten years.','她哥哥在海军服役了十年。'),('He chose a navy jacket and a white shirt.','他选了一件藏蓝色夹克和一件白衬衫。'),sources=['https://www.etymonline.com/word/navy','https://www.oxfordlearnersdictionaries.com/definition/english/navy']),
E('naval','/ˈneɪvəl/','海军的；军舰的','把事物放到海上军事力量这个范围里：基地、军官、作战等。','经法语 naval 或直接接拉丁 navalis，来自 navis“船”；现代对应 navy 的形容词，但并非历史上由英语 navy 现造。',N+[['拉丁语 navalis → 法语 naval / 英语 naval','船的 → 海军、军舰的']],'a naval base 是海军基地；a naval officer 是海军军官。它不表示藏蓝色，也不是一切与海洋有关的通用形容词。','a naval base；naval forces；a naval officer。','maritime 涉及航海、海事；naval 尤其聚焦海军。navel 是肚脐，另源同音。',('The ship returned to its naval base.','军舰返回了海军基地。'),('The museum displays old naval uniforms.','博物馆展出了旧式海军制服。'),sources=['https://www.etymonline.com/word/naval','https://www.oxfordlearnersdictionaries.com/definition/english/naval']),
E('nave','/neɪv/','教堂中殿；轮毂〔另源旧义〕','走进教堂后，通往前方圣坛区的主要长厅，通常就是中殿。','教堂义接中世纪拉丁 navis 的建筑用法，来自“船”，常以形状相似解释；轮毂义继承古英语 nafu，另属日耳曼来源。',N+[['中世纪拉丁语 navis / navem','由船的形状联想到教堂中殿'],['英语 nave〔教堂义〕','教堂主要长厅'],['另源并列：古英语 nafu → 中古英语 nave','车轮中央的轮毂，与船义分开']],'常见教堂导览中的 the nave，指主要空间，不只是地面上一条走道。建筑布局会有差异；不能把任何大厅都叫 nave。','the nave of the cathedral；a vaulted nave；walk through the nave。','aisle 是走道或侧廊；nave 是中殿这个主要空间。轮毂义在现代通常用 hub。',('Visitors entered the nave through the western doors.','游客从西侧的大门进入中殿。'),('Tall columns separate the nave from the side aisles.','高大的柱子把中殿和两侧的侧廊分开。'),sources=['https://www.etymonline.com/word/nave','https://www.oxfordlearnersdictionaries.com/definition/english/nave']),
E('navigable','/ˈnævɪɡəbəl/','可通航的；可顺利浏览、穿行的','水道有足够条件让船过去；网站或空间也可以让人顺利找路。','法语或拉丁 navigabilis 整词借入，接 navigare“航行”；现代能看出 navigate + -able 的对应，但英语形容词比 navigate 的常见记录更早。',NAVIGABLE,'a navigable river 要结合船的大小、水深和季节理解；a navigable website 说页面结构能让人找到需要的信息。法律中的“可航水域”另有具体判定语境。','a navigable river；navigable waters；an easily navigable site。','accessible 强调能到达、能使用；navigable 强调能够在其中移动或找到路线。',('The river is navigable by small boats in summer.','这条河夏季可以供小船航行。'),('Clear menus make the website easily navigable.','清晰的菜单让网站很容易浏览。'),sources=['https://www.etymonline.com/word/navigable','https://www.oxfordlearnersdictionaries.com/definition/english/navigable']),
E('navigability','/ˌnævɪɡəˈbɪləti/','通航能力；便于浏览、穿行的程度','不只问有没有水或页面，而是问实际能不能顺利走过去。','navigable + -ity，-able 变为 -ability；由可通行的性质形成抽象名词。',NAVIGABLE+[['英语 navigable → navigability','可通航的 → 通航条件、可浏览性']],'river navigability 会随水位、障碍、船型变化；website navigability 关注导航、层级是否帮助用户找路。','improve navigability；river navigability；the navigability of a website。','navigation 是找路、航行这项活动；navigability 是环境允许这项活动进行的程度。',('Fallen trees reduced the navigability of the narrow channel.','倒下的树木降低了狭窄航道的通航能力。'),('The redesign improved the navigability of the archive.','重新设计后，资料库更容易浏览和查找了。'),sources=['https://www.merriam-webster.com/dictionary/navigability','https://www.etymonline.com/word/navigable']),
E('navigator','英 /ˈnævɪɡeɪtə/；美 /ˈnævɪɡeɪtər/','领航员；负责找路的人；导航工具','先弄清自己在哪，再确定应该往哪走的那个人或工具。','借自拉丁 navigator，来自 navigare 的施事名词；现代可以对照 navigate + -or，但完整人物名词已存在于拉丁语。',NAVIG+[['拉丁语 navigator → 英语 navigator','领航的人 → 船舶、飞机等的领航员；导航工具']],'船舶或飞机的 navigator 负责定位、路线等；开车时坐副驾看地图的人也可开玩笑说是 navigator。这个角色不必亲自操纵方向盘。','a skilled navigator；the aircraft’s navigator；a satellite navigator。','pilot 常负责驾驶；navigator 主要负责定位和路线，实际职责可以重合。',('The navigator checked our position before we changed course.','领航员在我们改变航向前核对了位置。'),('I drove while my sister acted as navigator.','我开车，姐姐负责看路。'),sources=['https://www.etymonline.com/word/navigator','https://www.oxfordlearnersdictionaries.com/definition/english/navigator']),
E('navigational','/ˌnævɪˈɡeɪʃənəl/','导航的；航行定位的','用来回答“我在哪、下一步往哪走”的设备、信号或安排。','navigation + -al；navigation 本身经法语或拉丁 navigatio 借入，接 navigare。',NAVIG+[['拉丁语 navigatio → 法语 navigation / 英语 navigation','航行、确定路线'],['英语 navigation + -al → navigational','与定位、航行或找路有关的']],'navigational aids 可以是灯塔、浮标或仪器；软件里的 navigational elements 是菜单、链接等帮助用户移动的组件。','navigational aids；navigational equipment；a navigational error。','navigable 说对象能让人通行；navigational 说它与导航活动有关。',('The vessel carries modern navigational equipment.','这艘船配有现代导航设备。'),('The page keeps its navigational links in the left column.','页面把导航链接放在左侧栏。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/navigational','https://www.etymonline.com/word/navigation']),
E('circumnavigate','英 /ˌsɜːkəmˈnævɪɡeɪt/；美 /ˌsɜːrkəmˈnævɪɡeɪt/','环航；绕……一周','围着一个岛、陆地或地球走完一圈，而不只是从旁边经过。','来自拉丁 circumnavigatus、circumnavigare，circum-“周围” + navigare“航行”；现代也能按 circum- + navigate 理解。',CIRC,'最典型是 circumnavigate the globe；也可以绕岛航行。现代还可扩展到其他交通方式；关键是完成环绕路线。','circumnavigate the globe；circumnavigate an island；circumnavigate by sea。','circumvent 常指绕开障碍或规避规则；circumnavigate 主要是实际环绕行程。',('The crew plans to circumnavigate the island in two days.','船员们计划用两天绕岛航行一周。'),('She became the first person in her family to circumnavigate the globe.','她成为家里第一个完成环球旅行的人。'),sources=['https://www.etymonline.com/word/circumnavigate','https://www.oxfordlearnersdictionaries.com/definition/english/circumnavigate']),
E('circumnavigation','英 /ˌsɜːkəmˌnævɪˈɡeɪʃən/；美 /ˌsɜːrkəmˌnævɪˈɡeɪʃən/','环航；环绕一周的旅程','把出发点、整圈路线和返抵这件事看成一次完整行程。','circumnavigate + -ion，-ate 对应名词 -ation；英语名词从环航动词派生。',CIRC+[['英语 circumnavigate → circumnavigation','环航 → 环航行动或行程']],'a circumnavigation of the world 是环球行程；a solo circumnavigation 强调独自完成。词本身不规定必须不停靠或必须使用同一种交通工具。','complete a circumnavigation；a solo circumnavigation；a circumnavigation of the island。','voyage 只表示一次远航；circumnavigation 还包含绕目标一周的路线要求。',('The book describes a difficult circumnavigation of the world.','这本书描写了一次艰难的环球航行。'),('Their circumnavigation of the island ended at the harbour where it began.','他们绕岛一周后回到了出发的港口。'),sources=['https://www.etymonline.com/word/circumnavigation','https://www.merriam-webster.com/dictionary/circumnavigation']),
E('benign','/bɪˈnaɪn/','和善的；温和无害的；良性的','看起来没有伤害性，或带着温和、善意的态度；医学里则有更具体的分类义。','经古法语 benigne 接拉丁 benignus，传统分析联系 bene“好”与生育、出身的词根；从出身良好转为品性和善，再扩展到温和。',BENIGN,'a benign smile 是温和的微笑；a benign explanation 是无害、非恶意的解释。医学中的 benign tumor 指非癌性肿瘤，不等于它在任何位置、大小下都绝无影响。','a benign smile；a benign influence；a benign tumour。','benevolent 强调有善意、愿助人；benign 可只说不凶险或没有恶意。医学中与 malignant 相对。',('She watched the children with a benign smile.','她带着温和的微笑看着孩子们。'),('The report described the growth as benign.','报告将这个增生物描述为良性。'),sources=['https://www.etymonline.com/word/benign','https://www.oxfordlearnersdictionaries.com/definition/english/benign','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/benign']),
E('benignly','/bɪˈnaɪnli/','和善地；无害地','表情或行为没有攻击性，像带着温和的好意看待对方。','benign + -ly；保留 benign 中 g 不单独发音的读法。',BENIGN+[['英语 benign + -ly → benignly','温和、无恶意的 → 以这种方式']],'smile benignly 常描写温厚、宽容的神情；act benignly 也可说某种影响并不造成伤害。它不必包含主动捐助或帮助。','smile benignly；look benignly on；nod benignly。','kindly 常见于友善行动；benignly 更突出温和、不带威胁的状态或态度。',('The old man smiled benignly at the noisy children.','老人对吵闹的孩子们温和地笑了笑。'),('She nodded benignly and let him finish his story.','她和善地点点头，让他把故事讲完。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/benignly','https://www.etymonline.com/word/benign']),
E('benevolent','/bəˈnevələnt/','仁慈的；有善意的；乐善好施的','心里希望别人过得好，也愿意给予照顾或帮助。','拉丁 bene“好” + volens“想要”，形成 benevolens；经古法语或直接拉丁语借入。',VOL+[['拉丁语 benevolens → 古法语 benivolent / 英语 benevolent','希望别人好 → 有善意、乐于助人的']],'a benevolent person 是善心的人；a benevolent fund 是为帮助有需要者而设的基金。它描述意愿、性质，不自动证明每个决定都有效。','a benevolent attitude；a benevolent fund；a benevolent donor。','beneficial 强调结果有好处；benevolent 强调主观善意，两者不必总同时成立。',('A benevolent neighbour helped the family through a difficult winter.','一位善心的邻居帮助这家人度过了艰难的冬天。'),('The company set up a benevolent fund for former employees.','公司为以前的员工设立了援助基金。'),sources=['https://www.etymonline.com/word/benevolent','https://www.oxfordlearnersdictionaries.com/definition/english/benevolent']),
E('benevolence','/bəˈnevələns/','善意；仁慈；慈善帮助','把他人的处境放在心上，愿意为他们做点好事的心意与行为。','经法语 benivolence 或拉丁 benevolentia 借入；英语名词记录早于 benevolent，不能只按现代形容词换尾写历史。',VOL+[['拉丁语 benevolentia → 古法语 benivolence / 英语 benevolence','善意、好心 → 仁慈与帮助']],'an act of benevolence 是一次善举；depend on someone’s benevolence 是靠对方好心帮助。词义重点不是施助者多有钱，而是帮助意愿。','an act of benevolence；human benevolence；depend on someone’s benevolence。','beneficence 更聚焦行善、带来益处；benevolence 更突出善意和愿意助人的倾向。',('The shelter survives through the benevolence of local residents.','收容所靠当地居民的善心援助维持运作。'),('Her benevolence was clear in the way she treated new staff.','从她对待新员工的方式中，可以看出她的善意。'),sources=['https://www.etymonline.com/word/benevolence','https://www.oxfordlearnersdictionaries.com/definition/english/benevolence']),
E('beneficence','/bəˈnefɪsəns/','行善；施惠；促进他人福祉','不只在心里祝别人好，还要落实为对别人有帮助的行动。','借自拉丁 beneficentia，接 beneficus；bene“好”与 facere“做”这一支结合。',BENEF+[['拉丁语 beneficentia → 英语 beneficence','做好事、慷慨 → 行善、促进福祉']],'是较正式的词，可谈慈善行为，也可出现在伦理讨论里，强调让他人受益。它并不等于单纯避免伤害。','an act of beneficence；the principle of beneficence；public beneficence。','benevolence 偏善意；beneficence 偏善行和增进他人利益，实际用法有重叠。',('The lecture distinguished beneficence from the simple avoidance of harm.','讲座区分了主动促进他人福祉与仅仅避免伤害。'),('The library was built through the beneficence of local donors.','图书馆在当地捐赠者的善举支持下建成了。'),sources=['https://www.etymonline.com/word/beneficence','https://www.merriam-webster.com/dictionary/beneficence']),
E('beneficial','/ˌbenɪˈfɪʃəl/','有益的；带来好处的','看实际效果：它让某人、某个过程或某种处境变得更好。','经古法语 bénéficial 或拉丁 beneficialis 借入，源于 beneficium“恩惠、益处”；不是英语 benefit 直接加 -cial。',BENEFICIAL,'beneficial to someone 是对某人有益；mutually beneficial 是双方都受益。一个做法对甲有益，未必对乙也一样。','beneficial to；a beneficial effect；mutually beneficial。','benevolent 说善意；beneficial 说有益效果。beneficiary 则是获得好处的人。',('The new timetable is beneficial to students who commute.','新课表对需要通勤的学生有益。'),('The two groups reached a mutually beneficial agreement.','两个团体达成了一项互惠协议。'),sources=['https://www.etymonline.com/word/beneficial','https://www.oxfordlearnersdictionaries.com/definition/english/beneficial']),
E('beneficially','/ˌbenɪˈfɪʃəli/','有益地；在受益权上〔正式〕','普通义说产生好效果；正式文件里也可说谁实际享有某项权益。','beneficial + -ly，-cial 的读音与后接 -ly 合为 /ʃəli/；不把它与 beneficiary 混成同一个词。',BENEFICIAL+[['英语 beneficial + -ly → beneficially','有益的 → 以有益方式；也用于实际受益关系']],'affect beneficially 是产生有利影响。beneficially owned 常见于法律、商业文件，关注实际利益归属，不等同于谁在名义上持有。','affect beneficially；use beneficially；beneficially owned。','profitably 常说盈利或有成效；beneficially 的好处未必是利润，正式受益权义还须按语境理解。',('The extra funding affected the programme beneficially.','新增资金给这个项目带来了有利影响。'),('The report identifies the shares beneficially owned by each director.','报告列明了每位董事实际享有受益权益的股份。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/beneficially','https://www.merriam-webster.com/dictionary/beneficially']),
E('beneficiary','英 /ˌbenɪˈfɪʃəri/；美 /ˌbenɪˈfɪʃieri/','受益者；受益人','好处最后落到谁手里，谁就是 beneficiary。','接拉丁 beneficiarius“受到恩惠的”，可能经法语 bénéficiaire 借入；远接 beneficium，不从现代英语 benefit 直接加 -iary。',BENEF+[['拉丁语 beneficiarius → 可能经法语 bénéficiaire → 英语 beneficiary','享受恩惠的人 → 受益者、受益人']],'奖学金计划的 beneficiary 是得到帮助的人；保险、遗嘱等文件中的 beneficiary 是指定或依法享有相应利益的人。可以是个人，也可以是机构。','the main beneficiary；a beneficiary of；name someone as a beneficiary。','benefactor 是给予帮助的人；beneficiary 是接受好处的一方。',('Students are the main beneficiaries of the new transport scheme.','学生是新交通方案的主要受益者。'),('She named a local charity as a beneficiary in her will.','她在遗嘱中指定一家当地慈善机构为受益人。'),sources=['https://www.etymonline.com/word/beneficiary','https://www.oxfordlearnersdictionaries.com/definition/english/beneficiary']),
]
G=[['拉丁语 negare','否认、拒绝，说“不”']]
NEG=G+[['拉丁语 negativus → 法语 negatif / 直接借入英语','表示否定的'],['英语 negative','否定的；负的；消极的；阴性的等']]
DENY=G+[['拉丁语 de- + negare → denegare','加强拒绝、否认'],['古法语 denoier → 中古英语 denyen → deny','否认；拒绝给予']]
RENEGE=G+[['拉丁语 re- + negare → 中世纪拉丁语 renegare','re- 可能加强语气：否认、背弃'],['英语 renege','背弃原先的承诺或约定']]
D=[['拉丁语 domus','家、房屋、家庭']]
DOMESTIC=D+[['拉丁语 domesticus → 法语 domestique → 英语 domestic','家里的、家用的 → 家庭的；本国的']]
DOMESTICATE=D+[['拉丁语 domesticus → 中世纪拉丁语 domesticare / domesticatus','家里的 → 驯养、使适应家庭使用'],['英语 domesticate〔也可能经法语 domestiquer〕','驯化；使适应家庭生活']]
DOMICILE=D+[['拉丁语 domicilium → 法语 domicile / 英语 domicile','住所；后半通常联系居住，但具体构成有疑问']]
DOME=[['法语 dome / dôme 的较早来源有不同解释','一说接意大利 duomo、拉丁 domus；另一说涉及希腊 dōma“房屋、屋顶”'],['法语 dome → 英语 dome','堂宇、建筑 → 拱起的圆顶']]
W += [
E('negative','/ˈneɡətɪv/','否定的；负的；消极的；阴性的；底片','最早是说“不”，后来在不同系统里表示否定、缺少某项结果，或位于正的另一边。','由法语 negatif 或拉丁 negativus 借入，接 negare“否认”；不能把所有现代意思都翻成“不好”。',NEG,'negative feedback 是负面评价时可能不好；negative number 是小于零的数；a negative test result 表示该检测未检出目标，含义要看测什么。摄影的 a negative 是明暗、色彩反转的底片。','a negative attitude；a negative number；a negative result；a photographic negative。','positive / negative 的具体对应随领域变化；检测阴性不等于对任何问题都给出“完全正常”的结论。',('The temperature fell to a negative value overnight.','夜里气温降到了零度以下。'),('Her response was negative, so we tried another approach.','她的回应是否定的，因此我们尝试了另一种办法。'),('He found the original negatives in an old box.','他在一个旧盒子里找到了原始底片。'),sources=['https://www.etymonline.com/word/negative','https://www.oxfordlearnersdictionaries.com/definition/english/negative_1']),
E('negatively','/ˈneɡətɪvli/','负面地；否定地；带负电地等','把 negative 的不同方向放进动作或状态：反应不好、回答“不”，或具有负的属性。','negative + -ly；用法取决于 negative 在该句中是哪一个意思。',NEG+[['英语 negative + -ly → negatively','否定、消极、负的 → 以相应方式']],'react negatively 是作出不利或不赞成的反应；answer negatively 是作否定回答；negatively charged 是带负电，并不评价它有害。','react negatively；affect negatively；negatively charged。','badly 常表示不好；negatively 在科学或逻辑语境中可以完全中性。',('The delay affected customer satisfaction negatively.','延误对顾客满意度造成了负面影响。'),('The particles are negatively charged.','这些粒子带负电。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/negatively','https://en.wiktionary.org/wiki/negatively#English']),
E('negativity','/ˌneɡəˈtɪvəti/','消极态度；负面情绪；负性','总把注意力拉向坏处、失败和不可能，便形成一股消极气氛。','negative + -ity，形成性质名词；重音移到 /tɪv/，不是直接在 negative 后保持原重音。',NEG+[['英语 negative → negativity','消极、负的 → 消极态度或负的性质']],'日常常说 constant negativity，批评持续抱怨或否定一切的态度。在技术上下文也可指负的性质，不一定涉及情绪。','constant negativity；a culture of negativity；respond to negativity。','criticism 可以具体、有建设性；negativity 常着重一味消极的倾向。',('The team was tired of his constant negativity.','团队厌倦了他不断散发的消极态度。'),('She acknowledged the risks without slipping into negativity.','她承认风险，但没有因此陷入消极情绪。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/negativity','https://en.wiktionary.org/wiki/negativity#English']),
E('negate','/nɪˈɡeɪt/','使失效；抵消；否定','原本有的效果被抵掉了，或一个命题被加上“不成立”的方向。','可能从早已存在的 negation 反构，也可能借拉丁 negatus，接 negare；不能把 negation 一律画成现代 negate 的后代。',G+[['拉丁语 negatus；或较早英语 negation 的反构','否认的古典形式；英语名词先存在'],['英语 negate','否定、抵消作用']],'The cost negates the saving 是额外费用把节省抵掉了；逻辑中 negate a statement 是构造其否定。日常更常用于效果被抵消，而非随口说不。','negate the benefits；negate an effect；negate a statement。','deny 常是人拒绝承认某事；negate 可以是因素使另一效果失效，不需要有人开口。',('The extra fees negate most of the savings.','额外费用抵消了大部分节省。'),('Adding “not” can negate the meaning of a simple statement.','加上 not 可以否定一个简单陈述的意思。'),sources=['https://www.etymonline.com/word/negate','https://www.oxfordlearnersdictionaries.com/definition/english/negate']),
E('negation','/nɪˈɡeɪʃən/','否定；否认；与之相反或抵消的东西','给一个说法加上“不”，或把某种原则整个反过来。','经法语 negacion 或拉丁 negatio 借入，接 negare；英语名词早于 negate 的通常记录。',G+[['拉丁语 negatio → 古法语 negacion → 英语 negation','否认行为 → 逻辑、语法中的否定等']],'语法中的 negation 可通过 not、never 等表达。the negation of a principle 是对某原则的否定、背离，不一定仅指一句口头反对。','logical negation；double negation；the negation of a claim。','denial 常带某人否认某事实的行为；negation 还适合讨论语言、逻辑的否定结构。',('The lesson explains how English expresses negation.','这节课解释英语如何表达否定。'),('For her, censorship was the negation of free inquiry.','在她看来，审查制度是对自由探究的否定。'),sources=['https://www.etymonline.com/word/negation','https://www.oxfordlearnersdictionaries.com/definition/english/negation']),
E('deny','/dɪˈnaɪ/','否认；拒绝给予；不让得到','一条线是“那不是真的”，另一条线是“这个不给你”。','拉丁 denegare 由 de- + negare“拒绝、否认”构成，经古法语 denoier、中古英语 denyen 演变。',DENY,'deny doing something 是否认做过；deny someone access 是不让某人进入或使用。deny oneself a pleasure 则是克制自己，不享受某种乐趣。','deny an allegation；deny doing；deny someone access。','refuse to do 是拒绝去做；deny doing 是否认已经做过，时间和动作关系不同。',('She denied sharing the confidential file.','她否认分享过那份机密文件。'),('The system denied him access to the folder.','系统不允许他访问该文件夹。'),sources=['https://www.etymonline.com/word/deny','https://www.oxfordlearnersdictionaries.com/definition/english/deny']),
E('denial','/dɪˈnaɪəl/','否认；拒绝；不愿承认现实','有人说“没有那回事”，或者把某项申请、权利挡在门外。','deny + -al；y 变 i，构成行为名词。后来的 in denial 又用来描述不愿面对事实的状态。',DENY+[['英语 deny + -al → denial','否认、拒绝 → 这种行为、声明或心理状态']],'issue a denial 是发表否认声明；denial of access 是拒绝访问；be in denial 常说人不愿承认令人难受的现实。不能只看单词就判断否认是真是假。','a firm denial；denial of access；be in denial about。','rejection 常指拒绝接纳；denial 也可是否认某事实存在。',('The company issued a denial of the allegation.','公司发表声明否认了这项指控。'),('He was still in denial about the scale of the problem.','他仍不愿承认问题有多严重。'),sources=['https://www.etymonline.com/word/denial','https://www.oxfordlearnersdictionaries.com/definition/english/denial']),
E('undeniable','/ˌʌndɪˈnaɪəbəl/','不可否认的；明显存在的','证据或表现就摆在那里，很难诚实地说它不存在。','un-“不” + deniable“可否认的”，后者对应 deny + -able；两个否定方向合成“不能否认”。',DENY+[['英语 deny → deniable；un- + deniable → undeniable','可否认 → 不可否认']],'undeniable talent 是明摆着的才华；undeniable evidence 是难以否认的证据。它加强说话者的判断，不自动替代证据论证。','undeniable evidence；an undeniable fact；undeniable talent。','undeniable 强调无法否认存在或真实性；inevitable 强调无法避免发生。',('Her contribution to the project is undeniable.','她对项目的贡献无可否认。'),('There is undeniable evidence of water damage.','水损的证据清楚得无法否认。'),sources=['https://www.etymonline.com/word/undeniable','https://www.oxfordlearnersdictionaries.com/definition/english/undeniable']),
E('undeniably','/ˌʌndɪˈnaɪəbli/','不可否认地；确实','承认一个事实很明显，同时仍可继续讨论它的其他方面。','undeniable + -ly，-able 变 -ably；修饰形容词、动词或整句话。',DENY+[['英语 deniable → undeniable → undeniably','可否认 → 无法否认 → 确实、不可否认地']],'undeniably talented 是确实有才华；undeniably, the plan has risks 是先承认风险事实。它可以与 but 连用，承认一点而保留另一个判断。','undeniably important；undeniably talented；undeniably true。','probably 表示很可能；undeniably 表示说话者认为此事无法否认，确定程度更强。',('The design is undeniably elegant, but it is difficult to build.','这个设计确实优雅，但很难建造。'),('She is undeniably the most experienced member of the team.','她无疑是团队中经验最丰富的成员。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/undeniably','https://en.wiktionary.org/wiki/undeniably#English']),
E('renege','英 /rɪˈniːɡ/，也 /rɪˈneɪɡ/；美 /rɪˈneɡ/','背弃承诺；违约；食言','原先答应了，后来又不照那个约定办。','从中世纪拉丁 renegare 借入；re- 在此可能加强语气，接 negare“否认、拒绝”。不是 renegotiate 的缩写。',RENEGE,'常用 renege on a promise / agreement，不是直接 renege a promise。重点是背弃先前承担的承诺，带明显批评意味。','renege on a promise；renege on a deal；refuse to renege。','renegotiate 是重新谈判，可能经双方同意；renege 是不履行原承诺。',('The supplier reneged on its promise to deliver by Friday.','供应商没有履行周五前交货的承诺。'),('She refused to renege on the agreement.','她拒绝背弃那项协议。'),sources=['https://www.etymonline.com/word/renege','https://www.oxfordlearnersdictionaries.com/definition/english/renege']),
E('renegade','/ˈrenɪɡeɪd/','叛离者；不守本派规则的人；叛离的','离开原来的阵营，或拒绝按所属团体的规矩行事。','通常认为经西班牙 renegado 接中世纪拉丁 renegatus，是 renegare“否认、背弃”的分词名词化；不是英语 renege 加 -ade。',G+[['中世纪拉丁语 renegare → renegatus','背弃 → 背弃原立场的人'],['西班牙语 renegado → 英语 renegade','早期宗教叛离者 → 叛离者、不受约束者']],'历史用法可带强烈的“叛徒”评价；现代 a renegade artist 又可能带赞赏，说某人不守成规。要看是谁在评价、评价什么。','a renegade soldier；a renegade member；a renegade artist。','traitor 明确指背叛；renegade 也能只是偏离群体规则，未必有同样严重的道德指控。',('A renegade member voted against the party’s official position.','一位不服从党内立场的成员投了反对票。'),('The exhibition celebrates a group of renegade artists.','展览赞颂了一群不循常规的艺术家。'),sources=['https://www.etymonline.com/word/renegade','https://www.oxfordlearnersdictionaries.com/definition/english/renegade']),
E('domestic','/dəˈmestɪk/','家庭的；家用的；国内的；家养的','从“自己家里”向外扩一层，就能指“自己国家里面”。','经法语 domestique 接拉丁 domesticus，来自 domus“家”；不是英语 dome“圆顶”加 -stic。',DOMESTIC,'domestic chores 是家务；domestic appliances 是家用电器；domestic flights 是国内航班；domestic animals 是家养动物。名词旧用法还可指家佣，现代中性表达常用 domestic worker。','domestic life；domestic appliances；domestic flights；domestic animals。','domestic 与家庭、国内有关；domesticated 强调已经驯化或习惯家庭生活。',('The airport has separate terminals for domestic and international flights.','机场的国内航班和国际航班使用不同航站楼。'),('They share the domestic chores equally.','他们平均分担家务。'),sources=['https://www.etymonline.com/word/domestic','https://www.oxfordlearnersdictionaries.com/definition/english/domestic_1']),
E('domestically','/dəˈmestɪkli/','在国内；在家庭生活方面','可以把观察范围限定在本国，也可以限定在家庭内部。','domestic + -ally；-ically 的常用读法在这里压缩为 /ɪkli/。',DOMESTIC+[['英语 domestic → domestically','家庭、国内的 → 在家庭或本国范围内']],'produced domestically 是本国生产；domestically minded 则可能说重视家庭生活。商业、新闻里通常先考虑“国内”义。','produce domestically；sell domestically；domestically sourced materials。','locally 是当地，范围可能是一个城市；domestically 通常相对于国外，以国家为范围。',('Most of the components are produced domestically.','大部分零部件在国内生产。'),('The film performed well domestically but attracted little attention abroad.','这部电影在国内表现不错，在国外却没有引起多少关注。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/domestically','https://en.wiktionary.org/wiki/domestically#English']),
E('dome','英 /dəʊm/；美 /doʊm/','圆顶；穹顶；穹状物','像半个球或鼓起的罩子，从上方盖住一片空间。','近源是法语 dome。常见解释追到意大利 duomo“主教座堂”、拉丁 domus“家”；Etymonline 另列涉及普罗旺斯语、希腊 dōma“屋顶”的路线。',DOME,'a glass dome 可以是建筑顶，也可以是罩住物品的玻璃罩；a dome of snow 则借形状描写雪丘。不同穹顶并不都是精确的半球。','a glass dome；the dome of a building；a dome of snow。','roof 是屋顶总称；dome 特别强调向上弯起、覆盖空间的穹状外形。',('Sunlight entered through the glass dome.','阳光透过玻璃穹顶照了进来。'),('The cake was displayed beneath a clear dome.','蛋糕陈列在一个透明罩子下面。'),sources=['https://www.etymonline.com/word/dome','https://www.merriam-webster.com/dictionary/dome','https://www.oxfordlearnersdictionaries.com/definition/english/dome']),
E('domed','英 /dəʊmd/；美 /doʊmd/','有圆顶的；呈穹顶状的','顶端向上拱起，像盖着一个圆罩。','dome + -ed；可表示装有圆顶，也可表示本身拱成圆顶形。',DOME+[['英语 dome + -ed → domed','圆顶 → 有圆顶、呈穹状的']],'a domed ceiling 是穹顶天花板；a domed lid 是拱起的盖子。形容外形，不要求它是宗教建筑。','a domed roof；a domed ceiling；a domed lid。','arched 可以是一个拱面或弧线；domed 更像覆盖一片面积的圆拱罩。',('The hall has a high domed ceiling.','大厅有高高的穹顶天花板。'),('She lifted the domed lid from the serving dish.','她掀起了餐盘上拱起的盖子。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/domed','https://www.merriam-webster.com/dictionary/dome']),
E('domesticate','动词 /dəˈmestɪkeɪt/；名词 /dəˈmestɪkət/','驯化；使适应家居生活；驯化动植物〔名词〕','把原本野生的动植物逐渐纳入人类栽培、饲养的生活体系。','接中世纪拉丁 domesticatus，来自 domesticare；也可能经法语 domestiquer。现代可与 domestic + -ate 对照，但历史是借入古典派生形式。',DOMESTICATE,'常说 domesticate animals 或 plants。严格谈驯化时，通常涉及群体跨代变化，不是把一只野兽训练得听话就算完成。用于人则常是轻松说法，指习惯家庭生活。','domesticate a species；domesticate plants；become domesticated。','tame 可以指让某一只动物不怕人、听话；domesticate 通常谈更长期的饲养、培育与适应。',('Humans domesticated many plants long before modern farming machinery existed.','现代农业机械出现很久之前，人类就已驯化了许多植物。'),('The article asks how wolves came to be domesticated.','文章探讨狼是怎样逐渐被驯化的。'),sources=['https://www.etymonline.com/word/domesticate','https://www.merriam-webster.com/dictionary/domesticate']),
E('domesticated','/dəˈmestɪkeɪtɪd/','已驯化的；习惯家庭生活的','动植物已经进入长期的人类饲养或栽培关系；人也可以被打趣说很会过家居日子。','domesticate + -ed；末尾 /t/ 后读 /ɪd/，承接动词 /eɪt/ 的音节。',DOMESTICATE+[['英语 domesticate → domesticated','驯化 → 已驯化、习惯家庭生活的']],'domesticated animals 不等于所有住在屋里的动物；a domesticated man 是较口语、常带玩笑的家居型描述。用在人身上可能显得调侃，需看关系。','domesticated animals；domesticated crops；a domesticated lifestyle。','domestic 常是所属范围；domesticated 更强调经过驯化或养成家居习惯。',('The farm keeps several breeds of domesticated animals.','农场饲养着几种家养动物品种。'),('He joked that cooking every evening had made him thoroughly domesticated.','他开玩笑说，每晚做饭已经让自己彻底变成了居家型的人。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/domesticated','https://www.etymonline.com/word/domesticate']),
E('domestication','/dəˌmestɪˈkeɪʃən/','驯化；适应家居生活的过程','把野生种群与人的生活长期联系起来，经过一代代饲养、培育而发生变化。','domesticate + -ion，-ate 对应 -ation；是英语中表示动作、过程或状态的名词。',DOMESTICATE+[['英语 domesticate → domestication','驯化 → 长期驯化过程、驯化状态']],'the domestication of wheat 说作物驯化史；animal domestication 说动物与人类长期关系的变化。不能把它简化成某天某人第一次喂了一只动物。','plant domestication；animal domestication；the process of domestication。','training 是训练具体行为；domestication 讨论更长时段、涉及繁殖和群体变化的过程。',('The exhibition traces the domestication of cereal crops.','展览追溯了谷类作物的驯化过程。'),('Domestication changed the relationship between people and these animals.','驯化改变了人与这些动物之间的关系。'),sources=['https://www.etymonline.com/word/domestication','https://www.merriam-webster.com/dictionary/domestication']),
E('domesticity','/ˌdəʊmeˈstɪsəti/；美 /ˌdoʊmeˈstɪsəti/','家庭生活；居家气息','做饭、整理房间、相伴过日子组成的那一小片生活。','domestic + -ity，可能仿法语 domesticité；早期还有家佣身份义，后来重点落在家庭生活和居家性质。',DOMESTIC+[['英语 domestic + -ity → domesticity〔可能受法语 domesticité 影响〕','家庭的、家务的 → 家庭生活、居家气息']],'domesticity 可以是温暖安稳，也可能让人感到束缚，取决于语境。它说生活方式，不是统计意义上的“国内性”。','quiet domesticity；a scene of domesticity；the comforts of domesticity。','domestic life 是较直接的家庭生活；domesticity 更像把居家日子的气氛、状态整体拿出来谈。',('After years of travel, she enjoyed the quiet domesticity of village life.','旅行多年后，她很享受村居生活中安静的家庭日常。'),('The painting captures a moment of ordinary domesticity.','这幅画捕捉了普通家庭生活的一瞬。'),sources=['https://www.etymonline.com/word/domesticity','https://www.oxfordlearnersdictionaries.com/definition/english/domesticity']),
E('domicile','英 /ˈdɒmɪsaɪl/；美 /ˈdɑːmɪsaɪl/，也 /ˈdɑːmɪsəl/','住所；定居地；使定居','较正式地说一个人的家或固定归属地，不是每次短住的旅馆。','经法语或直接拉丁 domicilium 借入；一般与 domus“家”相连，后半是否接 colere“居住”保留疑问。英语动词后来从名词形成。',DOMICILE+[['英语 domicile〔名词〕→ domicile〔动词〕','固定住所、定居地 → 使在某处定居']],'普通正式文体可指住所；法律、税务文件中的 domicile 往往与长期归属、定居意图等有关，不能仅用一个现住地址替代所有语境的概念。','a permanent domicile；change one’s domicile；domicile in a country。','residence 常强调实际居住地；domicile 在正式语境可能强调更持久的归属，具体标准依制度而异。',('The form asks for your permanent domicile.','表格要求填写你的永久定居地。'),('The novel follows a family searching for a stable domicile.','小说讲述一家人寻找稳定居所的经历。'),sources=['https://www.etymonline.com/word/domicile','https://www.oxfordlearnersdictionaries.com/definition/english/domicile']),
E('domiciled','英 /ˈdɒmɪsaɪld/；美 /ˈdɑːmɪsaɪld/','定居于；登记或确定住所于','用正式语气标明某人或机构把哪儿作为住所、注册归属地。','domicile + -ed；是动词分词，常出现在 be domiciled in 结构中。',DOMICILE+[['英语 domicile〔动词〕→ domiciled','使定居 → 住所设在某处']],'个人可以 be domiciled in a country；公司或基金也可以用这一词描述注册、住所归属。它不单说明某位员工此刻在哪里办公。','be domiciled in；domiciled abroad；a locally domiciled company。','located 只是位于；domiciled 更正式，常涉及住所或机构归属。',('The document states that the company is domiciled in Canada.','文件写明这家公司的住所设在加拿大。'),('Although she travels frequently, she remains domiciled in her home country.','尽管经常旅行，她仍以自己的祖国为定居归属地。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/domiciled','https://www.etymonline.com/word/domicile']),
E('domiciliary','英 /ˌdɒmɪˈsɪliəri/；美 /ˌdɑːməˈsɪlieri/','居家的；在家提供的〔服务、护理等〕','服务人员来到住处提供照护，而不是让人每次都去服务机构。','经法语 domiciliaire 接中世纪拉丁 domiciliarius，来自 domicilium“住所”；不是英语 domicile 随便加 -iary。',DOMICILE[:-1]+[['拉丁语 domicilium → 中世纪拉丁语 domiciliarius','住所 → 与住所有关的'],['法语 domiciliaire → 英语 domiciliary','居家的；提供居住照护的']],'英式材料中的 domiciliary care 常指居家照护。部分美式机构用法也可指提供居住空间的照护，因此见到词不应机械断定一定是去本人原有住宅。','domiciliary care；a domiciliary visit；domiciliary services。','residential care 通常在提供住宿的机构内；domiciliary 在常见英式用法中侧重上门居家服务。',('The organisation provides domiciliary care for older residents.','这个组织为老年居民提供居家照护。'),('A nurse arranged a domiciliary visit for the following morning.','护士安排了第二天上午的上门探访。'),sources=['https://www.merriam-webster.com/dictionary/domiciliary','https://www.oxfordlearnersdictionaries.com/definition/english/domiciliary']),
]
DEFERRED={'navicular':'专门解剖、兽医学词，按最新范围暂缓。','nonnavigable':'低频透明否定派生，先集中学习 navigable。','benignity':'低频抽象名词，先学 benign、benevolence。','benignant':'罕用形容词。','astrodome':'专门航空导航观察舱或穹顶名称。','skydome':'较低频专名、专业或场馆用词。','domestique':'自行车竞技中的专门角色。','domal':'较专门形态形容词。','semidome':'较专门建筑术语。'}
NAV_ROOT=dict(id='C0797',meaning='船；航行、定位与路线',core='先有船，再有让船前进、知道往哪开的技术；这套“找位置、找路线”的思路后来也用于汽车、网页和复杂事务。',image='navis 船 → navy 舰队、海军；navis + agere 驱动 → navigate 航行、导航；circum- 绕周围 → circumnavigate 环航。',intro='主线来自拉丁 navis“船”。navigation、navigator、navigable 各自都有拉丁或法语来源，不能全部当成英语 navigate 现加后缀。nave 的教堂义是船形联想；轮毂义另接古英语，不能因为字一样就合并来源。',forms='nav- 是船；navig- 常连接 navigare，即 navis + agere“驱动”的古典复合。naval 表海军相关，navigational 表导航相关，navigable 表可供通行。navy 还从海军制服的颜色发展出藏蓝色义。',branches=[['船与海军','navy, naval, nave'],['找路与通行条件','navigate, navigation, navigator, navigational, navigable, navigability'],['绕行一周','circumnavigate, circumnavigation']],contrasts='naval 不等于 navy blue；navigational 与导航有关，navigable 是能顺利通过或浏览。nave 是中殿空间，aisle 是侧廊或走道。',practice='用 naval、navigational、navigable 分别修饰基地、设备、河流；再说明网站为什么也能称 easily navigable。',words=[w for w in ASSIGN['roots'][54]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][54]['family'] if w in DEFERRED})
BEN_ROOT=dict(id='C0117',meaning='好、善；善意、好处与帮助',core='要把三件事分开：心里希望别人好，行动让别人受益，最后谁得到好处。它们相连，却不是一回事。',image='bene + velle：希望别人好 → benevolent；bene + facere：做好事 → benefit、beneficial；beneficiary：好处落到的人；benign：温和、没有恶意。',intro='拉丁 bene 是“好地、以好的方式”。进入复合词后分别接表示愿望、行动、出生和说话的材料。benefit、benefactor、benediction 在其他词族也能遇到，因为一个词可以同时包含两个有意义的构词部分。',forms='bene- 常保留好、善的方向；benign 中的 beni- 是古老词形，g 在这个现代英语词里不单独读。benevolent 的 -volent 接 velle“希望”；beneficial 的 -fic- 接 facere“做”。名词 benevolence 在英语中早于 benevolent，别按长短倒排历史。',branches=[['温和与善意','benign, benignly, benevolent, benevolence'],['做好事与带来好处','benefit, beneficial, beneficially, beneficence, benefactor'],['受益与祝福','beneficiary, benediction']],contrasts='benefactor 给予帮助，beneficiary 获得利益；benevolent 有善意，beneficial 有益处。benign 的医学用法是非癌性，与日常“温和”相连但有专门意义。',practice='造一句区分“有善意但未必有帮助”：benevolent 与 beneficial 分别放在哪？再用 benefactor、beneficiary 说清帮助关系的两端。',words=[w for w in ASSIGN['roots'][55]['family'] if w not in DEFERRED]+['benefactor','benediction'],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][55]['family'] if w in DEFERRED})
NEG_ROOT=dict(id='C0804',meaning='否认、拒绝；说不、抵消与背弃',core='核心是说“不”：不承认是真的，不肯把东西给出去，或不再履行原来的承诺。',image='negare 说不 → negative 否定的；否定一个效果 → negate；denegare 拒绝、否认 → deny；renegare 背弃 → renege、renegade。',intro='拉丁 negare 表否认、拒绝，较远与否定材料 nec 相连。negative、negation、deny 经不同的法语或拉丁完整词进入英语；negate 反而较晚，可能从 negation 反构。renege 和 renegade 分别走动词借入与西班牙名词路线，不能互相按英语后缀推导。',forms='neg- 在古典材料中表示否认；de-、re- 在本族的作用要按具体历史看，不把 re- 总译成“再一次”。negative 的不同专业义不等于坏；deny + -al → denial，un- + deniable → undeniable。',branches=[['否定、负面与负的性质','negative, negatively, negativity'],['抵消与逻辑否定','negate, negation'],['否认与无法否认','deny, denial, undeniable, undeniably'],['背弃承诺或原阵营','renege, renegade']],contrasts='deny doing 是否认做过；refuse to do 是拒绝去做。renege on a deal 是背约，renegotiate 是重新协商。negative number 与 negative attitude 中的 negative 不能用一个“坏”字硬套。',practice='分别用 deny、negate、renege 写三个场景：否认指控、费用抵消收益、背弃承诺。解释 in denial 与 undeniable 为什么方向相反。',words=list(ASSIGN['roots'][56]['family']),exclude={})
DOM_ROOT=dict(id='C0337',meaning='家、房屋；家庭、国内、驯化与住所',core='从“家”出发，向内是家务与家庭生活，向外把本国当作自己的家；长期住进人类生活的动植物，又通往驯化。',image='domus 家 → domestic 家庭的、国内的；domesticate 纳入人类饲养栽培生活；domicile 固定住所；dome 从堂宇名称转向圆顶形状。',intro='主线来自拉丁 domus“房屋、家庭”。domestic、domicile 各自通过完整古典词借入。dame 通过“女主人”支线与房屋、主人关系相连。dome 的较早路线有不同词源解释：常见意大利 duomo、拉丁 domus 说，也有涉及希腊 dōma“房屋、屋顶”的解释，保留差异。',forms='domestic 的 -estic 是古典词形组成，不从现代英语 dome 硬拆。domesticate 接中世纪拉丁动词，domestication 才是英语过程名词。domiciliary 也有独立法语、拉丁形容词路线。',branches=[['家庭与本国范围','domestic, domestically, domesticity'],['驯化、家养与家居习惯','domesticate, domesticated, domestication'],['住所与居家服务','domicile, domiciled, domiciliary'],['房屋、圆顶与女主人支线','dome, domed, dame']],contrasts='domestic flight 是国内航班，不是家用飞机。domesticate 不等于训练一只动物。domicile 在正式文本里可能比暂时居住更强调持久归属；dome 则主要讲外形。',practice='把 domestic 用在家务、航班、动物三个不同场景中。再说清 domiciliary care 的常见英式场景，以及 domesticated 与 tame 为什么不完全相同。',words=[w for w in ASSIGN['roots'][57]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][57]['family'] if w in DEFERRED})
roots=[NAV_ROOT,BEN_ROOT,NEG_ROOT,DOM_ROOT]
expected={w for r in ASSIGN['roots'][54:58] for w in r['family'] if w in set(ASSIGN['owned_words']) and w not in DEFERRED}
assert {w['word'] for w in W}==expected,({w['word'] for w in W}-expected,expected-{w['word'] for w in W})
assert len(W)==len({w['word'] for w in W})
assert all(len(w['examples'])>=2 and all(len(e)==2 and all(e) for e in w['examples']) for w in W)
assert all(all(w.get(k) for k in ['ipa','meaning','sense','split','history','explanation','usage','contrast','sources']) for w in W)
assert all(all(len(h)==2 and all(h) for h in w['history']) for w in W)
for kind,data in [('roots',roots),('words',W)]: (OUT/f'{kind}_batch200_st_18.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
p=Path('.cache/batch200/rewrite_st_progress.json');progress=json.loads(p.read_text())
progress['completed_roots']=list(dict.fromkeys(progress['completed_roots']+[r['id'] for r in roots]))
progress['completed_words']=list(dict.fromkeys(progress['completed_words']+[w['word'] for w in W]))
progress['batches']=list(dict.fromkeys(progress['batches']+['batch200_st_18']))
progress.setdefault('deferred_words',{}).update(DEFERRED)
progress.update(next_root_index=58,next_root_id=ASSIGN['roots'][58]['id'],status='writing',active_script=None,active_written_words=0,active_note='st18 nav9/ben8/neg11/dom11=39 new words79 examples;9 very rare words deferred;6 shared references. Next veh/pur/ag/hero/scal/fix/migr, practical roots only.')
p.write_text(json.dumps(progress,ensure_ascii=False,indent=2)+'\n')
print('st18',len(roots),'roots',len(W),'words',sum(len(w['examples']) for w in W),'examples',len(DEFERRED),'deferred')
